    iron_bookedgeburnisher = { name = "Železni polirnik robov knjig", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni polirnik robov knjig za knjigoveze." },
    bronze_bookedgeburnisher = { name = "Bronast polirnik robov knjig", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast polirnik robov knjig za knjigoveze." },
    silver_bookedgeburnisher = { name = "Srebrn polirnik robov knjig", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn polirnik robov knjig za knjigoveze." },
    gilded_bookedgeburnisher = { name = "Pozlačen polirnik robov knjig", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen polirnik robov knjig za knjigoveze." },
