    master_bookedgeburnisher_atelier = { name = "Mojstrski bookedgeburnisher atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bookedgeburnisher_palace = { name = "Suverena bookedgeburnisher palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BookEdgeBurnisherMaker.ironStock=18; BookEdgeBurnisherMaker.bronzeStock=14; BookEdgeBurnisherMaker.woodStock=10; BookEdgeBurnisherMaker.leatherStock=8; BookEdgeBurnisherMaker.silverStock=8; BookEdgeBurnisherMaker.goldStock=6; BookEdgeBurnisherMaker.jewelStock=4; BookEdgeBurnisherMaker.pearlStock=4
BookEdgeBurnisherMaker.productStock = {}; BookEdgeBurnisherMaker.buildings = {}; BookEdgeBurnisherMaker.maker = nil; BookEdgeBurnisherMaker.activeMaking = {}; BookEdgeBurnisherMaker.totalProducts = 0; BookEdgeBurnisherMaker.dayTimer = 0
function BookEdgeBurnisherMaker.init() BookEdgeBurnisherMaker.ironStock=18; BookEdgeBurnisherMaker.bronzeStock=14; BookEdgeBurnisherMaker.woodStock=10; BookEdgeBurnisherMaker.leatherStock=8; BookEdgeBurnisherMaker.silverStock=8; BookEdgeBurnisherMaker.goldStock=6; BookEdgeBurnisherMaker.jewelStock=4; BookEdgeBurnisherMaker.pearlStock=4; BookEdgeBurnisherMaker.productStock={}; BookEdgeBurnisherMaker.buildings={}; BookEdgeBurnisherMaker.maker=nil; BookEdgeBurnisherMaker.activeMaking={}; BookEdgeBurnisherMaker.totalProducts=0; BookEdgeBurnisherMaker.dayTimer=0; print("[BookEdgeBurnisherMaker] Royal Book Edge Burnisher Maker System initialized (6 products, 4 buildings)") end
function BookEdgeBurnisherMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookEdgeBurnisherMaker.maker={name=n or ("Polirnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirnik najet: %s (spretnost: %d)",BookEdgeBurnisherMaker.maker.name,s),"success") end; return true end
function BookEdgeBurnisherMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookEdgeBurnisherMaker.build(id) local ok,e=BookEdgeBurnisherMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookEdgeBurnisherMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookEdgeBurnisherMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookEdgeBurnisherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookEdgeBurnisherMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookEdgeBurnisherMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookEdgeBurnisherMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookEdgeBurnisherMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookEdgeBurnisherMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookEdgeBurnisherMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookEdgeBurnisherMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookEdgeBurnisherMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookEdgeBurnisherMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookEdgeBurnisherMaker.buildings==0 then return false,"Potrebna polirna delavnica" end; if not BookEdgeBurnisherMaker.maker then return false,"Potreben polirnik" end; return true end
function BookEdgeBurnisherMaker.make(pt,qty) qty=qty or 1; local ok,e=BookEdgeBurnisherMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookEdgeBurnisherMaker.ironStock=BookEdgeBurnisherMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookEdgeBurnisherMaker.bronzeStock=BookEdgeBurnisherMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookEdgeBurnisherMaker.woodStock=BookEdgeBurnisherMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookEdgeBurnisherMaker.leatherStock=BookEdgeBurnisherMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookEdgeBurnisherMaker.silverStock=BookEdgeBurnisherMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookEdgeBurnisherMaker.goldStock=BookEdgeBurnisherMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookEdgeBurnisherMaker.jewelStock=BookEdgeBurnisherMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookEdgeBurnisherMaker.pearlStock=BookEdgeBurnisherMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookEdgeBurnisherMaker.maker then t=math.max(1,t-math.floor(BookEdgeBurnisherMaker.maker.skill/13)) end; table.insert(BookEdgeBurnisherMaker.activeMaking,{id="bookedgeburnisher_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookEdgeBurnisherMaker.completeMaking(m) local q=1.0+(BookEdgeBurnisherMaker.getQualityBonus()/100); if BookEdgeBurnisherMaker.maker then q=q+(BookEdgeBurnisherMaker.maker.skill/140) end; q=math.min(2.5,q); BookEdgeBurnisherMaker.productStock[m.productType]=(BookEdgeBurnisherMaker.productStock[m.productType] or 0)+m.quantity; BookEdgeBurnisherMaker.totalProducts=BookEdgeBurnisherMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookEdgeBurnisherMaker.maker then BookEdgeBurnisherMaker.maker.itemsMade=BookEdgeBurnisherMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookEdgeBurnisherMaker.maker.skill=math.min(100,BookEdgeBurnisherMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Polirnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookedgeburnisher.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookEdgeBurnisherMaker.update(dt) if not _G.state then return end; BookEdgeBurnisherMaker.dayTimer=BookEdgeBurnisherMaker.dayTimer+dt; if BookEdgeBurnisherMaker.dayTimer>=30 then BookEdgeBurnisherMaker.dayTimer=0; for i=#BookEdgeBurnisherMaker.activeMaking,1,-1 do local m=BookEdgeBurnisherMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookEdgeBurnisherMaker.completeMaking(m); table.remove(BookEdgeBurnisherMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookEdgeBurnisherMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookEdgeBurnisherMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookEdgeBurnisherMaker.getStats() return {ironStock=BookEdgeBurnisherMaker.ironStock,bronzeStock=BookEdgeBurnisherMaker.bronzeStock,woodStock=BookEdgeBurnisherMaker.woodStock,leatherStock=BookEdgeBurnisherMaker.leatherStock,silverStock=BookEdgeBurnisherMaker.silverStock,goldStock=BookEdgeBurnisherMaker.goldStock,jewelStock=BookEdgeBurnisherMaker.jewelStock,pearlStock=BookEdgeBurnisherMaker.pearlStock,productStock=BookEdgeBurnisherMaker.productStock,numBuildings=#BookEdgeBurnisherMaker.buildings,hasMaker=BookEdgeBurnisherMaker.maker~=nil,makerName=BookEdgeBurnisherMaker.maker and BookEdgeBurnisherMaker.maker.name or "—",makerSkill=BookEdgeBurnisherMaker.maker and BookEdgeBurnisherMaker.maker.skill or 0,activeMaking=#BookEdgeBurnisherMaker.activeMaking,totalProducts=BookEdgeBurnisherMaker.totalProducts} end
return BookEdgeBurnisherMaker
